void main() {
  final jobs = loadYaml(
    File('.github/workflows/build-macos.yml').readAsStringSync(),
  )['jobs'] as YamlMap;
  final steps = (jobs['build-macos-cli'] as YamlMap)['steps'] as YamlList;
  for (final s in steps) {
    final run = (s as YamlMap)['run'];
    if (run == null) continue;
    final text = run.toString();
    if (text.contains('update_git_mirror.sh')) {
      File('/tmp/step_mirror_update.sh').writeAsStringSync(text);
    }
    if (text.contains('git clone')) {
      File('/tmp/step_checkout.sh').writeAsStringSync(text);
    }
  }
  print('extracted');
}

