import 'dart:io';
import 'package:yaml/yaml.dart';

void main() {
  final jobs = loadYaml(
    File('.github/workflows/build-macos.yml').readAsStringSync(),
  )['jobs'] as YamlMap;
  final steps = (jobs['build-macos-cli'] as YamlMap)['steps'] as YamlList;
  for (final s in steps) {
    final step = s as YamlMap;
    final name = step['name']?.toString() ?? '';
    final run = step['run'];
    if (run == null) continue;
    if (name == 'Update local git mirrors') {
      File('/tmp/step_mirror_update.sh').writeAsStringSync(run.toString());
    }
    if (name == 'Checkout repository from local mirrors') {
      File('/tmp/step_checkout.sh').writeAsStringSync(run.toString());
    }
  }
  print('extracted');
}

